// scalar, unrolled 2 times by gcc: 2 elements per iteration, one accumulator sum
// gcc -Ofast -fno-tree-vectorize -march=native SUM.c -o SUM-scalar
double my_sum ( double V[], int N ) {
  double sum=0;
  for ( int i=0; i<N; i++ )
     sum = sum + V[i];
  return sum;
}

// vectorized by gcc (AVX2, 4 doubles per 256-bit register): 4 elements per iteration
// gcc -Ofast -march=native SUM.c -o SUM-simd
double my_sum ( double V[], int N ) {
  double sum=0;
  for ( int i=0; i<N; i++ )
     sum = sum + V[i];
  return sum;
}

// scalar, unrolled 4 times with 4 accumulators (variable expansion): 4 elements per iteration
// gcc -Ofast -funroll-loops -fvariable-expansion-in-unroller --param max-variable-expansions-in-unroller=3
//     --param max-unroll-times=4 -fno-tree-vectorize -march=native SUM.c -o SUM-scalar4
double my_sum ( double V[], int N ) {
  double sum=0;
  for ( int i=0; i<N; i++ )
     sum = sum + V[i];
  return sum;
}

// vectorized (4 doubles) and unrolled 4 times with 4 vector accumulators: 16 elements per iteration
// gcc -Ofast -funroll-loops -fvariable-expansion-in-unroller --param max-variable-expansions-in-unroller=3
//     --param max-unroll-times=4 -march=native SUM.c -o SUM-simd4
double my_sum ( double V[], int N ) {
  double sum=0;
  for ( int i=0; i<N; i++ )
     sum = sum + V[i];
  return sum;
}
